  } }];
}

try {
  var d = $('Compute New Time').first().json || {};
  var reason = d.rejectReason || 'outside-hours';
  var when = (d.friendlyDate || 'that day') + ' at ' + (d.slotLabel || 'that time');
  var hours = 'Survey visits run Monday to Friday 9am to 5pm only, with at least 48 hours notice. We do not survey on Saturdays, Sundays or bank holidays.';
  var tail = ' The existing appointment has NOT been changed and is still in place. Do NOT say it was rescheduled.';
  var msg;

  if (reason === 'bank-holiday') {
    msg = 'NOT RESCHEDULED. ' + when + ' falls on a bank holiday and we do not carry out surveys then. ' + hours + tail + ' Offer to check another day.';
  } else if (reason === 'closed-day') {
    msg = 'NOT RESCHEDULED. We are closed on ' + (d.friendlyDate || 'that day') + '. ' + hours + tail + ' Offer to check another day.';
  } else if (reason === 'too-soon') {
    msg = 'NOT RESCHEDULED. ' + when + ' is inside our 48 hour notice window, and we need at least 48 hours to rearrange a surveyor. ' + tail + ' Offer the next working day.';
  } else if (reason === 'bad-time') {
    msg = 'NOT RESCHEDULED. That time was not recognised as one of our bookable slots.' + tail + ' Ask the customer to pick a slot on the hour between 9am and 5pm.';
  } else if (reason === 'error') {
    msg = 'NOT RESCHEDULED. A system error stopped the change being processed. ' + tail + ' Ask them to try again shortly.';
  } else {
    msg = 'NOT RESCHEDULED. ' + when + ' is outside our survey hours. ' + hours + tail + ' Offer a time inside those hours.';
  }

  return [{ json: { toolCallId: d.toolUseId || '', result: msg } }];
} catch (e) {
  return [{ json: { toolCallId: '', result: 'NOT RESCHEDULED. That time is outside our survey hours and the original appointment still stands. Offer Monday to Friday 9am to 5pm, at least 48 hours ahead, instead.' } }];
}

